steps.script:
$ErrorActionPreference='Continue'
$dir='C:\TTiTTulares\image-approval-receipts'
$o=@{cycle_present=$false;receipts=0;pending_errors=@();task_state='';last_result=-1;cycle=$null}
$t=Get-ScheduledTask -TaskName 'TT Actualidad - Entrega IA gradual' -ErrorAction SilentlyContinue
if($t){$o.task_state=[string]$t.State;$i=Get-ScheduledTaskInfo -TaskName $t.TaskName -ErrorAction SilentlyContinue;if($i){$o.last_result=$i.LastTaskResult}}
if(Test-Path $dir){
 $c=Join-Path $dir 'receiver-cycle.json'
 if(Test-Path $c){try{$d=Get-Content $c -Raw|ConvertFrom-Json;$o.cycle_present=$true;$o.cycle=@{checkedAt=$d.checkedAt;queuedLocal=$d.queuedLocal;eligible=$d.eligibleForApproval;attempted=$d.attemptedThisCycle;projects=$d.projects}}catch{}}
 $o.receipts=@(Get-ChildItem $dir -File -Filter '*.json' -ErrorAction SilentlyContinue|Where-Object{$_.Name -like 'tr-img-*' -or $_.Name -like 'tt-img-*'}).Count
 $p=Join-Path $dir 'receiver-status.json'
 if(Test-Path $p){try{$d=Get-Content $p -Raw|ConvertFrom-Json;$o.pending_errors=@($d.PSObject.Properties|Sort-Object {$_.Value.checkedAt} -Descending|Select-Object -First 12|ForEach-Object {@{id=$_.Name;reason=$_.Value.reason;checkedAt=$_.Value.checkedAt}})}catch{}}
}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 6))
